<div class="page-heading"><div><div class="eyebrow">PLAYBOOK / BIBLIOTECA</div><h1>Fichas <em>tácticas</em></h1><p>Organiza estrategias y lineups por mapa y bando.</p></div><?php if(isCoach()):?><a class="btn btn-primary" href="<?=e(url('tactica-editar'))?>">+ Nueva ficha</a><?php endif;?></div><section class="panel filter-panel"><form method="get" class="inline-filter"><input type="hidden" name="page" value="tacticas"><label>Filtrar por mapa<select name="map" onchange="this.form.submit()"><option value="0">Todos los mapas</option><?php foreach($maps as $m):?><option value="<?=e($m['id_mapa'])?>" <?=(int)$map===(int)$m['id_mapa']?'selected':''?>><?=e($m['nombre_mapa'])?><?=((int)$m['activo_competitivo']===1?' · Activo':' · Histórico')?></option><?php endforeach;?></select></label><button class="btn">Aplicar filtro</button></form></section><div class="tactics-grid"><?php foreach($items as $it):?><article class="panel tactic-card"><div class="card-top"><span class="chip"><?=e($it['nombre_mapa'])?></span><span class="chip <?=e($it['bando']==='Atacante'?'victoria':'')?>"><?=e($it['bando'])?></span></div><h2><?=e($it['titulo'])?></h2><div class="eyebrow">AGENTE CLAVE · <?=e($it['agente_clave'])?></div><p class="preline"><?=e($it['descripcion'])?></p><div class="card-bottom"><small>Por <?=e($it['nickname_valorant'])?></small><div class="actions"><?php if($it['link_vod']):?><a href="<?=e($it['link_vod'])?>" rel="noopener noreferrer" target="_blank" class="btn small">Ver VOD ↗</a><?php endif;?><?php if(isCoach()):?><a href="<?=e(url('tactica-editar',['id'=>$it['id_estrategia']]))?>" class="btn small">Editar</a><form method="post" action="<?=e(url('tactica-eliminar'))?>" data-confirm="¿Eliminar esta ficha?"><?=csrfField()?><input type="hidden" name="id" value="<?=e($it['id_estrategia'])?>"><button class="btn small danger">Eliminar</button></form><?php endif;?></div></div></article><?php endforeach;?><?php if(!$items):?><div class="panel">No se encontraron fichas tácticas.</div><?php endif;?></div>
